import html as _html
import pathlib

import pandas as pd


STYLE = """
  body { font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
         margin: 2rem auto; max-width: 1040px; padding: 0 1rem; color: #1a1a1a; }
  h1 { font-size: 1.5rem; margin-bottom: .2rem; }
  .sub { color: #666; margin-top: 0; font-size: .9rem; }
  .note { background: #fff8e1; border: 1px solid #ffe082; padding: .55rem .8rem;
          border-radius: 6px; font-size: .82rem; color: #7a5b00; margin: 1rem 0 1.4rem; }
  table { border-collapse: collapse; width: 100%; font-size: .9rem; }
  th, td { text-align: left; padding: .5rem .6rem; border-bottom: 1px solid #ececec;
           vertical-align: top; }
  th { background: #fafafa; font-size: .72rem; text-transform: uppercase;
       letter-spacing: .04em; color: #555; }
  td.rank { font-weight: 700; color: #9aa0a6; }
  td.num { font-variant-numeric: tabular-nums; font-weight: 600; white-space: nowrap; }
  td.muted { color: #777; }
  .pill { background: #eef2ff; color: #3730a3; padding: .12rem .55rem;
          border-radius: 999px; font-size: .78rem; white-space: nowrap; }
  .bill-yes { color: #166534; font-weight: 600; }
  .bill-no { color: #9ca3af; }
"""


def _cell(value):
    return "<td>" + _html.escape(str(value)) + "</td>"


def transform(df, output_dir):
    # The publish handler points output_dir at run_dir/artifacts/<name> but does
    # NOT create it; create it here so writing the report never FileNotFoundErrors.
    pathlib.Path(output_dir).mkdir(parents=True, exist_ok=True)

    body_rows = []
    for _, row in df.iterrows():
        targets_bill = bool(row["targets_specific_bill"])
        bill_html = (
            "<td class='bill-yes'>Yes</td>" if targets_bill else "<td class='bill-no'>No</td>"
        )
        cells = (
            "<td class='rank'>" + str(int(row["spend_rank"])) + "</td>"
            + _cell(row["client"])
            + "<td class='muted'>" + _html.escape(str(row["registrant"])) + "</td>"
            + _cell(row["filing_period"])
            + "<td class='num'>$" + format(int(row["amount_usd"]), ",") + "</td>"
            + "<td><span class='pill'>" + _html.escape(str(row["policy_area"])) + "</span></td>"
            + bill_html
            + _cell(row["primary_ask"])
        )
        body_rows.append("<tr>" + cells + "</tr>")

    html_doc = (
        "<!DOCTYPE html>\n<html lang='en'>\n<head>\n<meta charset='UTF-8'>\n"
        "<title>Lobbying Disclosure Triage</title>\n<style>" + STYLE + "</style>\n"
        "</head>\n<body>\n"
        "<h1>Lobbying Disclosure Triage Report</h1>\n"
        "<p class='sub'>" + str(len(df)) + " filings, ranked by reported spend (highest first).</p>\n"
        "<p class='note'>Illustrative / synthetic sample data — not live Senate LDA "
        "filings. This report is a reading aid, not a verdict.</p>\n"
        "<table>\n<thead><tr>"
        "<th>Rank</th><th>Client</th><th>Registrant</th><th>Period</th>"
        "<th>Reported spend</th><th>Policy area</th><th>Targets a bill?</th><th>Primary ask</th>"
        "</tr></thead>\n<tbody>\n" + "\n".join(body_rows) + "\n</tbody>\n</table>\n"
        "</body>\n</html>\n"
    )

    out_path = pathlib.Path(output_dir) / "triage_report.html"
    out_path.write_text(html_doc, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "filing_count": len(df)}])
